import sys
from collections import defaultdict

sys.setrecursionlimit(20000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    iterator = iter(input_data)

    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        b = [int(next(iterator)) for _ in range(n)]
        w = [int(next(iterator)) for _ in range(n)]

        adj = [[] for _ in range(n)]
        for _ in range(n - 1):
            u = int(next(iterator)) - 1
            v = int(next(iterator)) - 1
            adj[u].append(v)
            adj[v].append(u)

        diff = [w[i] - b[i] for i in range(n)]

        parent = [-1] * n
        order = []
        stack = [0]
        visited = [False] * n
        visited[0] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        dp = [[-float('inf')] * (m + 1) for _ in range(n)]

        for i in range(n - 1, -1, -1):
            u = order[i]

            children = []
            for v in adj[u]:
                if v != parent[u]:
                    children.append(v)

            current_dp = [-float('inf')] * (m + 1)
            current_dp[1] = 1 if diff[u] > 0 else 0

            for v in children:
                child_dp = dp[v]
                new_dp = [-float('inf')] * (m + 1)

                for k in range(1, m + 1):
                    if current_dp[k] == -float('inf'):
                        continue
                    for j in range(1, m + 1 - k):
                        if child_dp[j] == -float('inf'):
                            continue
                        if new_dp[k + j] < current_dp[k] + child_dp[j]:
                            new_dp[k + j] = current_dp[k] + child_dp[j]

                for k in range(m, 0, -1):
                    if current_dp[k] == -float('inf'): continue
                    if new_dp[k] < current_dp[k]:
                        new_dp[k] = current_dp[k]

                current_dp = new_dp

            dp[u] = current_dp

        ans = dp[0][m]
        if ans == -float('inf'):
            ans = 0
        out_lines.append(str(ans))

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == '__main__':
    solve()
